CREATE TABLE IF NOT EXISTS asset_community_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, claim_type text NOT NULL, claimant_name text NOT NULL, claimant_category text NOT NULL DEFAULT 'Community', community_name text, traditional_authority text, claim_summary text NOT NULL, claimed_interest text NOT NULL, geographic_scope text, origin_date date, status text NOT NULL DEFAULT 'Submitted', materiality text NOT NULL DEFAULT 'Material', verification_status text NOT NULL DEFAULT 'Unverified', evidence_count integer NOT NULL DEFAULT 0, blocking boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS community_claim_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), claim_id uuid NOT NULL REFERENCES asset_community_claims(id) ON DELETE CASCADE, evidence_type text NOT NULL, title text NOT NULL, source_reference text, evidence_summary text, verification_status text NOT NULL DEFAULT 'Unverified', submitted_at timestamptz NOT NULL DEFAULT now(), verified_at timestamptz, reviewer_reference text, status text NOT NULL DEFAULT 'Submitted');
CREATE TABLE IF NOT EXISTS community_grievances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, claim_id uuid REFERENCES asset_community_claims(id) ON DELETE SET NULL, grievance_code text NOT NULL UNIQUE, complainant_name text, complainant_category text, grievance_type text NOT NULL, summary text NOT NULL, preferred_resolution text, status text NOT NULL DEFAULT 'Open', intake_channel text NOT NULL DEFAULT 'Platform', confidentiality_level text NOT NULL DEFAULT 'Protected', opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, outcome_summary text); 
CREATE TABLE IF NOT EXISTS community_resolution_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), grievance_id uuid NOT NULL REFERENCES community_grievances(id) ON DELETE CASCADE, action_type text NOT NULL, actor_reference text, action_summary text NOT NULL, decision text, evidence_reference text, occurred_at timestamptz NOT NULL DEFAULT now(), next_action text, status text NOT NULL DEFAULT 'Recorded');
CREATE TABLE IF NOT EXISTS asset_rights_safeguard_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, decision_type text NOT NULL, decision text NOT NULL, reason text NOT NULL, blocking_claim_count integer NOT NULL DEFAULT 0, blocking_grievance_count integer NOT NULL DEFAULT 0, resolved_claim_count integer NOT NULL DEFAULT 0, decided_at timestamptz NOT NULL DEFAULT now(), reviewer_reference text, status text NOT NULL DEFAULT 'Active');
CREATE INDEX IF NOT EXISTS idx_community_claims_asset ON asset_community_claims(asset_id,status,blocking);
CREATE INDEX IF NOT EXISTS idx_claim_evidence_claim ON community_claim_evidence(claim_id,verification_status);
CREATE INDEX IF NOT EXISTS idx_grievances_asset ON community_grievances(asset_id,status);
CREATE INDEX IF NOT EXISTS idx_safeguard_asset ON asset_rights_safeguard_decisions(asset_id,decided_at DESC);